/* ORACLE-END */

export default async ({ page, toolURL, screenshot, assert }) => {
  const near = (a, b, tol, msg) =>
    assert(Math.abs(a - b) <= tol, `${msg}: ${a} vs ${b}（差 ${Math.abs(a - b).toPrecision(3)}，容差 ${tol}）`);
  const txt = (sel) => page.textContent(sel).then((s) => (s || '').trim());
  const M2FT = 3.280839895013123;

  await page.goto(toolURL);
  await page.waitForSelector('#td-daychart path', { timeout: 15000 });

  /* ── 1. 页面骨架 ───────────────────────────────────────────────── */
  assert(await page.title() === '潮汐工作台 · Tide Lab', '标题');
  assert(await page.getAttribute('a.td-back', 'href') === '../../', '返回工具集链接');
  const TABS = ['forecast', 'window', 'cons', 'analysis', 'about'];
  for (const t of TABS) assert(await page.$(`#tab-${t}`), `页签 ${t} 存在`);

  /* [hidden] 守卫：断计算样式，不是断属性（属性为真而视觉未藏正是这个坑的形态） */
  for (const t of TABS.slice(1)) {
    const disp = await page.$eval(`#pane-${t}`, (n) => getComputedStyle(n).display);
    assert(disp === 'none', `未选中的面板 ${t} 计算样式应为 none，实为 ${disp}`);
  }
  await page.click('#tab-about');
  assert(await page.$eval('#pane-about', (n) => getComputedStyle(n).display) !== 'none', '切到说明页后应可见');
  assert(await page.$eval('#pane-forecast', (n) => getComputedStyle(n).display) === 'none', '离开预报页后应隐藏');
  await page.click('#tab-forecast');

  /* ── 2. 预报：与 NOAA 官方高低潮表逐条对拍 ─────────────────────── */
  async function setup(o) {
    await page.fill('#td-search', o.id);
    await page.waitForTimeout(250);
    const n = await page.$$eval('#td-stationlist button', (ns) => ns.length);
    if (n !== 1) throw new Error(`按站号 ${o.id} 搜索应只命中 1 个测站，实际 ${n} 个`);
    await page.click('#td-stationlist button');
    await page.waitForTimeout(250);
    await page.selectOption('#td-datum', o.datum);
    await page.click(`#td-units button[data-u="${o.unit}"]`);
    await page.click(`#td-tz button[data-z="${o.tz}"]`);
    await page.fill('#td-date', o.date);
    await page.dispatchEvent('#td-date', 'change');
    await page.waitForTimeout(600);
  }
  /* pon（波多黎各 Ponce）潮差只有十几厘米，当天的原始导数过零点有 4 个，
     而 NOAA 官方高低潮表只报 2 个 —— 专门用来验「伪高低潮剔除」这条口径。 */
  for (const key of ['sf', 'anc', 'pon']) {
    const S = ORACLE[key];
    await setup({ id: S.id, datum: 'MSL', unit: 'm', tz: 'utc', date: S.day });
    const head = await txt('#td-dayhead');
    assert(head.indexOf(S.name) >= 0 && head.indexOf(S.day) >= 0, `${key} 标题含站名与日期：${head}`);

    const rows = await page.$$eval('#td-hilo tbody tr', (trs) =>
      trs.map((tr) => Array.from(tr.children).map((td) => td.textContent.trim())));
    assert(rows.length === S.hilo.length,
      `${key} 高低潮条数应为 NOAA 官方表的 ${S.hilo.length}，实为 ${rows.length}`);
    for (let i = 0; i < S.hilo.length; i++) {
      const want = S.hilo[i], got = rows[i];
      const [gh, gm] = got[0].split(':').map(Number), [wh, wm] = want.time.split(':').map(Number);
      const dMin = Math.abs((gh * 60 + gm) - (wh * 60 + wm));
      assert(dMin <= 3, `${key} 第 ${i + 1} 次高低潮时刻 ${got[0]} vs NOAA ${want.time}`);
      assert(got[1] === (want.type === 'H' ? '高潮' : '低潮'), `${key} 第 ${i + 1} 次类型 ${got[1]} vs ${want.type}`);
      near(parseFloat(got[2]), want.v, 0.0051, `${key} 第 ${i + 1} 次潮高（米）`);
    }

    /* 当日统计：与 NOAA 官方 6 分钟预报序列的极值对拍（异源） */
    const stat = await page.$$eval('#td-daystat div', (ds) =>
      Object.fromEntries(ds.map((d) => [d.querySelector('dt').textContent.trim(),
        parseFloat(d.querySelector('dd').textContent)])));
    near(stat['当日最高潮位'], S.maxV, 0.01, `${key} 当日最高潮位`);
    near(stat['当日最低潮位'], S.minV, 0.01, `${key} 当日最低潮位`);
    near(stat['当日潮差'], S.rangeV, 0.02, `${key} 当日潮差`);
    near(stat['正午潮位'], S.noonV, 0.01, `${key} 正午潮位（UTC 12:00）`);

    /* 七日潮汐表：NOAA 官方表里的每一次高低潮都必须出现在对应行里（零漏报）。
       反过来不成立 —— 极平缓的站上本页会多报几次毫米级的转折，NOAA 把它们滤掉了；
       这类多报按「相邻高差」计数并封顶，不能假装两边逐格相等。 */
    const week = await page.$$eval('#td-week tbody tr', (trs) =>
      trs.map((tr) => ({ day: tr.getAttribute('data-day'),
                         c: Array.from(tr.children).map((td) => td.textContent.trim()) })));
    assert(week.length === 7, `${key} 七日潮汐表应有 7 行，实为 ${week.length}`);
    let weekChecked = 0, weekExtra = 0;
    for (let d = 0; d < 7; d++) {
      const want = S.week[d];
      assert(week[d].day === want.date, `${key} 第 ${d + 1} 行日期 ${week[d].day} 应为 ${want.date}`);
      const cells = week[d].c.slice(1, 5).filter((c) => c !== '—').map((c) => {
        const m = c.match(/^(高|低)\s+(\d{2}:\d{2})\s+\/\s+(-?[\d.]+)$/);
        assert(m, `${key} ${want.date} 单元格格式应为「高 HH:MM / 高度」，实为 ${c}`);
        const [h, mi] = m[2].split(':').map(Number);
        return { type: m[1] === '高' ? 'H' : 'L', min: h * 60 + mi, v: parseFloat(m[3]), raw: c };
      });
      /* NOAA 的事件必须按序全部命中（前四格放得下的那些） */
      let ci = 0;
      for (let j = 0; j < Math.min(want.ev.length, 4); j++) {
        const e = want.ev[j];
        const [wh, wm] = e.time.split(':').map(Number);
        const wmin = wh * 60 + wm;
        let hit = -1;
        for (let q = ci; q < cells.length; q++) {
          if (cells[q].type === e.type && Math.abs(cells[q].min - wmin) <= 3) { hit = q; break; }
        }
        assert(hit >= 0, `${key} ${want.date} 缺了 NOAA 的 ${e.type}${e.time}（本行：${cells.map((c) => c.raw).join(' | ')}）`);
        near(cells[hit].v, e.v, 0.0051, `${key} ${want.date} ${e.time} 潮高`);
        weekExtra += hit - ci;
        ci = hit + 1;
        weekChecked++;
      }
      weekExtra += Math.max(0, cells.length - ci - Math.max(0, want.ev.length - 4));
    }
    assert(weekChecked >= 18, `${key} 七日表应逐格核对 ≥18 次高低潮，实际 ${weekChecked}`);
    assert(weekExtra <= 3, `${key} 七日表多报的毫米级转折应 ≤3 次，实际 ${weekExtra}`);

    /* 分潮个数：与 NOAA /harcon.json 返回的条数对拍 */
    const info = await page.$$eval('#td-stationinfo div', (ds) =>
      Object.fromEntries(ds.map((d) => [d.querySelector('dt').textContent.trim(), d.querySelector('dd').textContent.trim()])));
    assert(+info['分潮个数'] === S.nCon, `${key} 分潮个数 ${info['分潮个数']} vs NOAA ${S.nCon}`);
    assert(info['站号'] === S.id, `${key} 站号`);
  }

  /* 缺 MSL 的测站：不能提供别的基准面选项（否则会把 MSL 相对值贴上 MHHW 的标签） */
  await setup({ id: ORACLE.noDatum.id, datum: 'MSL', unit: 'm', tz: 'utc', date: ORACLE.sf.day });
  const dopt = await page.$$eval('#td-datum option', (ns) => ns.map((n) => n.value));
  assert(dopt.length === 1 && dopt[0] === 'MSL',
    `${ORACLE.noDatum.name} 没有公布 MSL（只有 ${ORACLE.noDatum.datums.join(',')}），基准面下拉应只剩 MSL，实际 ${dopt.join(',')}`);
  assert((await txt('#td-daysub')).indexOf('未公布可换算的潮汐基准面') >= 0, '缺基准面的站应在页面上说明');

  /* ── 3. 单位 / 基准面 / 时区 的换算 ───────────────────────────── */
  const S = ORACLE.sf;
  await setup({ id: S.id, datum: 'MSL', unit: 'm', tz: 'utc', date: S.day });
  const hiM = await page.$$eval('#td-hilo tbody tr', (trs) => trs.map((t) => parseFloat(t.children[2].textContent)));
  await page.click('#td-units button[data-u="ft"]');
  await page.waitForTimeout(400);
  const hiF = await page.$$eval('#td-hilo tbody tr', (trs) => trs.map((t) => parseFloat(t.children[2].textContent)));
  for (let i = 0; i < hiM.length; i++) near(hiF[i], hiM[i] * M2FT, 0.02, `第 ${i + 1} 项换算成英尺`);
  assert((await txt('#td-daysub')).indexOf('英尺') >= 0, '副标题应显示英尺');
  await page.click('#td-units button[data-u="m"]');
  await page.waitForTimeout(300);

  await page.selectOption('#td-datum', 'MLLW');
  await page.waitForTimeout(400);
  const hiD = await page.$$eval('#td-hilo tbody tr', (trs) => trs.map((t) => parseFloat(t.children[2].textContent)));
  const shift = (S.datums.MSL - S.datums.MLLW);
  for (let i = 0; i < hiM.length; i++) near(hiD[i], hiM[i] + shift, 0.01, `第 ${i + 1} 项换算到 MLLW（偏移 ${shift.toFixed(3)} 米）`);
  await page.selectOption('#td-datum', 'MSL');
  await page.waitForTimeout(300);

  const utcTimes = await page.$$eval('#td-hilo tbody tr', (trs) => trs.map((t) => t.children[0].textContent.trim()));
  await page.click('#td-tz button[data-z="local"]');
  await page.waitForTimeout(500);
  const locSub = await txt('#td-daysub');
  assert(locSub.indexOf('UTC-8') >= 0 || locSub.indexOf('PST') >= 0, `当地时区标注：${locSub}`);
  await page.click('#td-tz button[data-z="utc"]');
  await page.waitForTimeout(400);
  const back = await page.$$eval('#td-hilo tbody tr', (trs) => trs.map((t) => t.children[0].textContent.trim()));
  assert(JSON.stringify(back) === JSON.stringify(utcTimes), '切回 UTC 后时刻应还原');

  /* ── 4. 日月：与 PyEphem 对拍 ─────────────────────────────────── */
  for (const key of ['sf', 'anc']) {
    const Sk = ORACLE[key], sky = ORACLE.sky[key];
    await setup({ id: Sk.id, datum: 'MSL', unit: 'm', tz: 'local', date: Sk.day });
    const stat = await page.$$eval('#td-daystat div', (ds) =>
      Object.fromEntries(ds.map((d) => [d.querySelector('dt').textContent.trim(), d.querySelector('dd').textContent.trim()])));
    const toMin = (s) => { const [h, m] = s.trim().split(':').map(Number); return h * 60 + m; };
    const refMin = (iso) => {
      if (!iso) return null;
      const d = new Date(iso + 'Z'), local = new Date(d.getTime() + sky.tzoff * 3600000);
      return local.getUTCHours() * 60 + local.getUTCMinutes();
    };
    const [sr, ss] = stat['日出 · 日落'].split('·');
    if (sky.sunrise) near(toMin(sr), refMin(sky.sunrise), 1.5, `${key} 日出（分钟）`);
    if (sky.sunset) near(toMin(ss), refMin(sky.sunset), 1.5, `${key} 日落（分钟）`);
    const illum = parseFloat(stat['月相'].match(/(\d+)%/)[1]);
    near(illum, sky.illum * 100, 1.2, `${key} 月亮被照亮比例（%）`);
  }

  /* ── 5. 窗口筛选：结果要经得起 NOAA 官方 6 分钟预报的复核 ───────── */
  await setup({ id: S.id, datum: 'MSL', unit: 'm', tz: 'utc', date: S.day });
  await page.click('#tab-window');
  await page.waitForTimeout(300);
  await page.fill('#td-wstart', S.day);
  await page.dispatchEvent('#td-wstart', 'change');
  await page.fill('#td-wdays', '10');
  await page.dispatchEvent('#td-wdays', 'change');
  await page.click('#td-wdir button[data-d="below"]');
  await page.fill('#td-wlevel', '-0.3');
  await page.fill('#td-wmin', '0');
  await page.selectOption('#td-wlight', 'any');
  await page.click('#td-wrun');
  await page.waitForTimeout(2500);
  const wrows = await page.$$eval('#td-wtable tbody tr', (trs) =>
    trs.map((tr) => ({ c: Array.from(tr.children).map((td) => td.textContent.trim()),
                       a: +tr.getAttribute('data-a'), b: +tr.getAttribute('data-b') })));
  assert(wrows.length > 0 && wrows[0].c.length === 6, `应筛出窗口，实际 ${wrows.length} 行`);
  /* 每个窗口的「窗内极值」必须真的低于阈值；窗口内每个 NOAA 官方采样点也必须低于阈值 */
  const idx = new Map(ORACLE.sfWindow);
  let checked = 0;
  for (const r of wrows) {
    const ext = parseFloat(r.c[4]);
    assert(ext <= -0.3 + 1e-6, `窗内极值 ${ext} 应 ≤ -0.3`);
    /* 表格里的起止时刻必须与行上带的绝对时间戳一致（防止跨零点被渲染成同一天） */
    const fmt = (ms) => { const d = new Date(ms); return String(d.getUTCHours()).padStart(2, '0') + ':' + String(d.getUTCMinutes()).padStart(2, '0'); };
    assert(r.c[1] === fmt(r.a), `起始时刻文本 ${r.c[1]} 应等于时间戳 ${fmt(r.a)}`);
    assert(r.c[2].slice(0, 5) === fmt(r.b), `结束时刻文本 ${r.c[2]} 应等于时间戳 ${fmt(r.b)}`);
    const crossed = new Date(r.a).getUTCDate() !== new Date(r.b).getUTCDate();
    assert(crossed === (r.c[2].indexOf('次日') >= 0), `跨零点标记应与实际一致：${r.c[0]} ${r.c[1]}–${r.c[2]}`);
    for (const [t, v] of idx) {
      if (t > r.a + 60000 && t < r.b - 60000) { assert(v <= -0.3 + 0.01, `${r.c[0]} ${r.c[1]}–${r.c[2]} 窗口内 NOAA 官方预报 ${v} 应 ≤ -0.3`); checked++; }
    }
  }
  assert(checked >= 40, `窗口应覆盖到至少 40 个 NOAA 官方采样点用于交叉复核，实际 ${checked}`);
  /* 反向：窗口之外、NOAA 官方预报确实低于阈值的时刻，不该被漏掉（窗口最短时长设为 0） */
  let missed = 0;
  for (const [t, v] of idx) {
    if (v > -0.3 - 0.02) continue;
    let inside = false;
    for (const r of wrows) { if (t >= r.a - 60000 && t <= r.b + 60000) { inside = true; break; } }
    if (!inside) missed++;
  }
  assert(missed === 0, `有 ${missed} 个 NOAA 官方预报低于阈值的时刻没被任何窗口覆盖（漏报）`);
  /* 窗口总时长必须与表格逐行时长之和一致（页面自述与逐行读数的自洽） */
  const sumH = wrows.reduce((s, r) => {
    const m = r.c[3].match(/(\d+)\s*时\s*(\d+)\s*分/);
    return s + (+m[1]) + (+m[2]) / 60;
  }, 0);
  const declared = parseFloat((await txt('#td-wsum')).match(/合计\s*([\d.]+)\s*小时/)[1]);
  near(sumH, declared, 0.4, '窗口总时长（逐行之和 vs 页面公布）');
  const bars = await page.$$eval('#td-wchart rect', (ns) => ns.length);
  assert(bars >= wrows.length, `窗口分布图应画出至少 ${wrows.length} 条线段，实为 ${bars}`);

  /* ── 6. 分潮页：与 NOAA /harcon.json 原始返回对拍 ───────────────── */
  await page.click('#tab-cons');
  await page.waitForTimeout(2500);
  const ctab = await page.$$eval('#td-constable tbody tr', (trs) =>
    trs.map((tr) => Array.from(tr.children).map((td) => td.textContent.trim())));
  assert(ctab.length === S.nCon, `分潮表行数 ${ctab.length} 应为 ${S.nCon}`);
  let chk = 0;
  for (const r of ctab) {
    const ref = S.harcon[r[0]];
    assert(ref, `分潮 ${r[0]} 应在 NOAA 原始返回里`);
    near(parseFloat(r[1]), ref.s, 5e-6, `${r[0]} 角速率`);
    near(parseFloat(r[3]), ref.a, 5e-4, `${r[0]} 振幅`);
    near(parseFloat(r[4]), ref.p, 0.06, `${r[0]} 迟角`);
    near(parseFloat(r[2]), 360 / ref.s, 0.01, `${r[0]} 周期 = 360/σ`);
    chk++;
  }
  assert(chk === S.nCon, `应逐行核对 ${S.nCon} 个分潮`);
  const fstat = await page.$$eval('#td-formstat div', (ds) =>
    Object.fromEntries(ds.map((d) => [d.querySelector('dt').textContent.trim(), d.querySelector('dd').textContent.trim()])));
  near(parseFloat(fstat['形数 F']), S.formFactor, 0.002, '形数 F');
  assert(fstat['潮型'].length >= 3, '潮型应有文字判定');
  /* 贡献图：柱子数与单调性 */
  const barH = await page.$$eval('#td-conschart rect', (ns) =>
    ns.filter((n) => n.getAttribute('fill') && n.getAttribute('fill').indexOf('rgba') === 0).map((n) => +n.getAttribute('height')));
  assert(barH.length >= 10, `贡献图柱子应 ≥10 根，实为 ${barH.length}`);
  for (let i = 1; i < barH.length; i++) {
    assert(barH[i] <= barH[i - 1] + 0.5, `贡献图第 ${i + 1} 根柱子应不高于前一根（加入分潮后残差只会变小）`);
  }
  const phLines = await page.$$eval('#td-phasor line', (ns) => ns.length);
  assert(phLines >= 12, `相量图应画出相量，实为 ${phLines} 条线`);
  /* 相量图上标注最密：文字两两不许重叠，且要真的画出足够多 */
  for (const id of ['td-phasor', 'td-conschart']) {
    const ov = await page.$eval('#' + id, (svg) => {
      const bs = Array.from(svg.querySelectorAll('text')).map((t) => {
        const b = t.getBBox();
        return { x: b.x, y: b.y, w: b.width, h: b.height, s: t.textContent };
      });
      const out = [];
      for (let i = 0; i < bs.length; i++) {
        for (let j = i + 1; j < bs.length; j++) {
          const a = bs[i], c = bs[j];
          if (a.x < c.x + c.w - 1 && c.x < a.x + a.w - 1 && a.y < c.y + c.h - 1 && c.y < a.y + a.h - 1) out.push(`「${a.s}」×「${c.s}」`);
        }
      }
      return { out: out, n: bs.length };
    });
    assert(ov.out.length === 0, `${id} 文字重叠：${ov.out.slice(0, 5).join(' ')}`);
    assert(ov.n >= 14, `${id} 应画出 ≥14 段文字，实为 ${ov.n}`);
  }
  /* 相量图上各分潮标注必须真的画出来（只断「掉了几个」在单峰数据上测不出） */
  const phNames = await page.$$eval('#td-phasor text', (ns) => ns.map((n) => n.textContent));
  for (const nm of ['M2', 'S2', 'N2', 'K1', 'O1', 'P1']) {
    assert(phNames.indexOf(nm) >= 0, `相量图应标出 ${nm}，实际标注：${phNames.filter((x) => /^[A-Z0-9]{2,5}$/.test(x)).join(',')}`);
  }

  /* ── 7. 调和分析：与 utide 独立实现对拍 ─────────────────────────── */
  await page.click('#tab-analysis');
  await page.waitForTimeout(300);
  await page.click(`#td-demos button[data-id="${ORACLE.sf.id}"]`);
  await page.waitForTimeout(1200);
  const nLines = await page.$eval('#td-obs', (n) => n.value.split('\n').length);
  assert(nLines === ORACLE.demoLen, `内置样本应有 ${ORACLE.demoLen} 行逐时实测，实为 ${nLines} 行`);
  await page.selectOption('#td-conset', 'noaa37');
  await page.click('#td-runfit');
  await page.waitForSelector('#td-fittable tbody tr', { timeout: 60000 });
  await page.waitForTimeout(1500);
  const frows = await page.$$eval('#td-fittable tbody tr', (trs) =>
    trs.map((tr) => Array.from(tr.children).map((td) => td.textContent.trim())));
  const UM = { NU2: 'NU2', LAM2: 'LDA2', RHO: 'RHO1', MU2: 'MU2' };
  const LONG = new Set(['SA', 'SSA', 'MM', 'MF', 'MSF', 'S1', 'R2']);
  let cmp = 0;
  for (const r of frows) {
    const u = ORACLE.utide.res[UM[r[0]] || r[0]];
    if (!u || LONG.has(r[0])) continue;
    near(parseFloat(r[1]), u.A, 0.0015, `${r[0]} 反演振幅 vs utide`);
    const dg = ((parseFloat(r[4]) - u.g + 180) % 360 + 360) % 360 - 180;
    assert(Math.abs(dg) <= 6, `${r[0]} 反演迟角与 utide 差 ${dg.toFixed(2)}°`);
    cmp++;
  }
  assert(cmp >= 20, `应与 utide 比对 ≥20 个分潮，实际 ${cmp}`);
  const fstat2 = await page.$$eval('#td-fitstat div', (ds) =>
    Object.fromEntries(ds.map((d) => [d.querySelector('dt').textContent.trim(), d.querySelector('dd').textContent.trim()])));
  assert(+fstat2['样本点数'] === nLines, `样本点数应等于输入行数`);
  const r2 = parseFloat(fstat2['解释方差 R²']);
  assert(r2 > 0.9 && r2 < 1, `R² 应在 (0.9,1)，实为 ${r2}`);
  assert(await page.$$eval('#td-fitchart path', (ns) => ns.length) >= 2, '拟合图应有观测与拟合两条曲线');
  assert(await page.$$eval('#td-residchart path', (ns) => ns.length) >= 1, '残差图应有曲线');

  /* 合成信号往返：把预报当成观测喂回去，应当逐位还原（不依赖任何外部实现的自洽性质） */
  const rt = await page.evaluate((sid) => {
    const st = TD.station(sid), hc = TDData.harcon(st), rows = [];
    for (let i = 0; i < 24 * 90; i++) {
      const t = Date.UTC(2026, 0, 1) + i * 3600000;
      rows.push({ t: t, v: TDTide.predictAt(hc, t) });
    }
    const names = hc.map((c) => c.name).filter((n) => ['M2', 'S2', 'N2', 'K1', 'O1', 'P1', 'K2', 'Q1'].indexOf(n) >= 0);
    const res = TDTide.analyze(rows, names);
    let worst = 0;
    res.constituents.forEach((c) => {
      const ref = hc.filter((x) => x.name === c.name)[0];
      worst = Math.max(worst, Math.abs(c.amp - ref.amp));
    });
    return { worst: worst, rms: res.rms };
  }, ORACLE.sf.id);
  assert(rt.worst < 0.02, `合成信号往返：8 个主要分潮振幅最大偏差 ${rt.worst}（其余分潮被折叠进残差，阈值放宽到 2 厘米）`);

  /* ── 8. 结构性守卫 ───────────────────────────────────────────── */
  /* 8a. 控件最小尺寸 —— 逐页签扫一遍（隐藏面板里的控件对尺寸守卫是失明的） */
  let ctrlCount = 0;
  for (const t of TABS) {
    await page.click(`#tab-${t}`);
    await page.waitForTimeout(500);
    const bad = await page.evaluate(() => {
      const out = [];
      let n = 0;
      document.querySelectorAll('input,select,button,textarea').forEach((el) => {
        const cs = getComputedStyle(el);
        if (cs.display === 'none' || cs.visibility === 'hidden') return;
        const r = el.getBoundingClientRect();
        if (r.width === 0 && r.height === 0) return;
        n++;
        const isBtn = el.tagName === 'BUTTON';
        const minW = isBtn ? 52 : (el.type === 'checkbox' ? 18 : 100);
        if (r.width < minW || r.height < 18) {
          out.push(`${el.tagName}#${el.id || ''}.${el.className} ${r.width.toFixed(1)}x${r.height.toFixed(1)} (需 ≥${minW}x18)`);
        }
      });
      return { out: out, n: n };
    });
    ctrlCount += bad.n;
    assert(bad.out.length === 0, `页签 ${t} 有塌缩控件：${bad.out.join(' | ')}`);
  }
  assert(ctrlCount >= 40, `逐页签累计扫到的可见控件应 ≥40，实为 ${ctrlCount}（扫不到就等于没测）`);

  /* 8b. text-transform 守卫：断计算样式（CSS 只改渲染字形、不改 DOM 文本，扫文本恒绿） */
  for (const t of TABS) {
    await page.click(`#tab-${t}`);
    await page.waitForTimeout(300);
    const up = await page.evaluate(() => {
      const bad = [];
      let n = 0;
      document.querySelectorAll('th,dt,label,.td-lab,.td-fact,caption').forEach((el) => {
        const cs = getComputedStyle(el);
        if (cs.display === 'none') return;
        n++;
        if (cs.textTransform !== 'none') bad.push(el.tagName + ':' + el.textContent.trim().slice(0, 14) + '→' + cs.textTransform);
      });
      return { bad: bad, n: n };
    });
    assert(up.bad.length === 0, `页签 ${t} 有被 CSS 改写大小写的标签：${up.bad.join(' | ')}`);
    assert(up.n > 0, `页签 ${t} 应扫到标签元素`);
  }

  /* 8c. 逐视口 × 逐页签的横向溢出（宽视口下网格有富余，测不出 min-width:auto 的坑） */
  for (const vw of [390, 768, 1280]) {
    await page.setViewportSize({ width: vw, height: 900 });
    for (const t of TABS) {
      await page.click(`#tab-${t}`);
      await page.waitForTimeout(400);
      const info = await page.evaluate(() => {
        const de = document.documentElement;
        const over = de.scrollWidth - de.clientWidth;
        const culprits = [];
        if (over > 1) {
          document.querySelectorAll('*').forEach((el) => {
            const r = el.getBoundingClientRect();
            if (r.width > 0 && r.right > de.clientWidth + 1) {
              culprits.push(`${el.tagName}#${el.id || ''}.${String(el.className).slice(0, 24)} right=${r.right.toFixed(0)}`);
            }
          });
        }
        return { over: over, culprits: culprits.slice(0, 6) };
      });
      assert(info.over <= 1, `${vw}px 下页签 ${t} 横向溢出 ${info.over}px：${info.culprits.join(' | ')}`);
    }
  }
  await page.setViewportSize({ width: 1280, height: 850 });

  /* 8d. SVG 文字两两不重叠 + 落在画布内 */
  await page.click('#tab-forecast');
  await page.waitForTimeout(800);
  for (const id of ['td-daychart', 'td-monthchart']) {
    const bad = await page.$eval('#' + id, (svg) => {
      const bs = Array.from(svg.querySelectorAll('text')).map((t) => {
        const b = t.getBBox();
        return { x: b.x, y: b.y, w: b.width, h: b.height, s: t.textContent };
      });
      const out = [];
      for (let i = 0; i < bs.length; i++) {
        for (let j = i + 1; j < bs.length; j++) {
          const a = bs[i], c = bs[j];
          if (a.x < c.x + c.w - 1 && c.x < a.x + a.w - 1 && a.y < c.y + c.h - 1 && c.y < a.y + a.h - 1) {
            out.push(`「${a.s}」×「${c.s}」`);
          }
        }
      }
      return { out: out, n: bs.length };
    });
    assert(bad.out.length === 0, `${id} 文字重叠：${bad.out.slice(0, 5).join(' ')}`);
    assert(bad.n >= 8, `${id} 应画出坐标刻度与标注文字，实为 ${bad.n} 段`);
  }

  /* 8e. 卡片内子元素不越出卡片（布局逃逸守卫） */
  const escaped = await page.evaluate(() => {
    const out = [];
    document.querySelectorAll('#pane-forecast .td-card').forEach((card) => {
      const cb = card.getBoundingClientRect();
      card.querySelectorAll('svg,table,dl,h2,p').forEach((el) => {
        const r = el.getBoundingClientRect();
        if (r.width === 0) return;
        if (r.left < cb.left - 1 || r.right > cb.right + 1) out.push(el.tagName + ' 越出卡片');
      });
    });
    return out;
  });
  assert(escaped.length === 0, `卡片内元素越界：${escaped.slice(0, 4).join(' | ')}`);

  /* ── 9. 能力清单与公布数字（异源核对；同源推导的守卫恒真） ───────── */
  await page.click('#tab-about');
  await page.waitForTimeout(400);
  const srcRows = await page.$$eval('#td-sources div', (ds) =>
    ds.map((d) => [d.querySelector('dt').textContent.trim(), d.querySelector('dd').textContent.trim()]));
  assert(srcRows.length >= 8, `数据来源清单应 ≥8 条，实为 ${srcRows.length}`);
  for (const [k, v] of srcRows) assert(k.length > 1 && v.length > 1, `来源条目「${k}」不能为空`);
  const stNum = srcRows.find((r) => r[0].indexOf('测站数') >= 0);
  assert(stNum && parseInt(stNum[1], 10) === ORACLE.nStations,
    `页面公布的测站数应为 ${ORACLE.nStations}（由 NOAA 原始数据文件数出），实为 ${stNum && stNum[1]}`);
  const conNum = srcRows.find((r) => r[0].indexOf('分潮定义数') >= 0);
  assert(conNum && parseInt(conNum[1], 10) === ORACLE.nConstituents,
    `页面公布的分潮定义数应为 ${ORACLE.nConstituents}，实为 ${conNum && conNum[1]}`);
  const vRows = await page.$$eval('#td-valid div', (ds) =>
    ds.map((d) => [d.querySelector('dt').textContent.trim(), d.querySelector('dd').textContent.trim()]));
  assert(vRows.length >= 5, `校验规模应 ≥5 条，实为 ${vRows.length}`);
  const predRow = vRows.find((r) => r[0].indexOf('逐点对拍') >= 0);
  assert(predRow && predRow[1].indexOf(ORACLE.validation.nPts.toLocaleString('en-US')) >= 0,
    `公布的对拍点数应为 ${ORACLE.validation.nPts.toLocaleString('en-US')}：${predRow && predRow[1]}`);
  const hiRow = vRows.find((r) => r[0].indexOf('高低潮表') >= 0);
  assert(hiRow && hiRow[1].indexOf(ORACLE.validation.hiN.toLocaleString('en-US')) >= 0,
    `公布的高低潮对拍次数应为 ${ORACLE.validation.hiN.toLocaleString('en-US')}：${hiRow && hiRow[1]}`);
  /* 首屏标签必须由实测数字生成（不是手打的宣传语）：逐条与离线套件的产出比对 */
  const factArr = await page.$$eval('.td-fact', (ns) => ns.map((n) => n.textContent.trim()));
  assert(factArr[0] === ORACLE.nStations + ' 个验潮站', `首屏第 1 个标签应为「${ORACLE.nStations} 个验潮站」，实为 ${factArr[0]}`);
  assert(factArr[1] === ORACLE.nConstituents + ' 个分潮定义', `首屏第 2 个标签应为「${ORACLE.nConstituents} 个分潮定义」，实为 ${factArr[1]}`);
  for (const f of ORACLE.validation.facts) {
    assert(factArr.indexOf(f) >= 0, `首屏标签应含离线套件实测出来的「${f}」，实际：${factArr.join(' | ')}`);
  }
  const oRow = vRows.find((r) => r[0].indexOf('除安克雷奇外') >= 0);
  assert(oRow && oRow[1].indexOf(ORACLE.validation.oRmsMm.toFixed(3)) >= 0,
    `说明页应公布除安克雷奇外的均方根 ${ORACLE.validation.oRmsMm.toFixed(3)} 毫米：${oRow && oRow[1]}`);
  assert(+(await txt('#td-nstations')) === ORACLE.nStations, '左栏测站数');
  const listed = await page.evaluate(() => TDData.STATIONS.length);
  assert(listed === ORACLE.nStations, `内置站点数组长度 ${listed} 应为 ${ORACLE.nStations}`);

  /* ── 10. 状态持久化与分享码 ─────────────────────────────────── */
  await page.click('#tab-forecast');
  await setup({ id: ORACLE.anc.id, datum: 'MSL', unit: 'ft', tz: 'utc', date: ORACLE.anc.day });
  const hashed = await page.evaluate(() => location.hash);
  assert(hashed.indexOf('s=') >= 0 && hashed.indexOf(ORACLE.anc.id) >= 0, `分享码应写进 URL：${hashed}`);
  await page.reload();
  await page.waitForSelector('#td-daychart path', { timeout: 15000 });
  const afterHead = await txt('#td-dayhead');
  assert(afterHead.indexOf(ORACLE.anc.name) >= 0, `刷新后应恢复到 ${ORACLE.anc.name}，实为 ${afterHead}`);
  assert((await txt('#td-daysub')).indexOf('英尺') >= 0, '刷新后应恢复英尺单位');

  /* 缩略图：清掉 localStorage 与 URL 分享码，拍「第一次打开」的默认视图（旧金山 · 当天 · MLLW · 测站当地时），
     否则会把上一步测出来的安克雷奇/英尺/UTC 状态拍进卡片（2026-09-23 实撞）。 */
  await page.evaluate(() => { try { localStorage.clear(); } catch (e) {} });
  await page.goto(toolURL);
  await page.waitForSelector('#td-daychart path', { timeout: 15000 });
  await page.waitForTimeout(1200);
  const thumbHead = await txt('#td-dayhead');
  assert(thumbHead.indexOf(ORACLE.sf.name) >= 0, `缩略图应拍默认视图（${ORACLE.sf.name}），实为 ${thumbHead}`);
  assert((await txt('#td-daysub')).indexOf('MLLW') >= 0, '缩略图应是默认的 MLLW 基准面');
  await screenshot('thumb.png');
};
